CREATE OR REPLACE FUNCTION headcount(p_department_id IN NUMBER) RETURN NUMBER IS
  l_count NUMBER;
BEGIN
  SELECT COUNT(*) INTO l_count FROM HARNESS_APP.EMPLOYEES WHERE department_id = p_department_id;
  RETURN l_count;
END headcount;

CREATE OR REPLACE FUNCTION salary_for(p_last_name IN VARCHAR2) RETURN NUMBER IS
  l_salary employees.salary%TYPE;
BEGIN
  SELECT salary INTO l_salary FROM employees WHERE last_name = p_last_name;
  RETURN l_salary;
EXCEPTION
  WHEN TOO_MANY_ROWS THEN
    RAISE_APPLICATION_ERROR(
      -20001,
      'Multiple employees match last_name=' || p_last_name
    );
END salary_for;
/

CREATE OR REPLACE FUNCTION display_name(p_employee_id IN NUMBER) RETURN VARCHAR2 IS
  l_name VARCHAR2(46);
BEGIN
  SELECT first_name || ' ' || last_name INTO l_name
    FROM employees WHERE employee_id = p_employee_id;
  RETURN l_name;
END display_name;

