CREATE OR REPLACE PROCEDURE HARNESS_APP.archive_old_orders(
  p_cutoff_date DATE
)
AS
  l_cur SYS_REFCURSOR;
  TYPE t_rows IS TABLE OF HARNESS_APP.ORDERS%ROWTYPE;
  l_rows t_rows;
BEGIN
  OPEN l_cur FOR
    SELECT ORDER_ID,
           CUSTOMER_ID,
           ORDER_DATE,
           STATUS,
           TOTAL
      FROM HARNESS_APP.ORDERS
     WHERE ORDER_DATE < p_cutoff_date
     ORDER BY ORDER_ID;

  LOOP
    FETCH l_cur BULK COLLECT INTO l_rows LIMIT 10000;
    EXIT WHEN l_rows.COUNT = 0;

    FORALL i IN INDICES OF l_rows
      INSERT INTO HARNESS_APP.ORDERS_ARCHIVE (
        ORDER_ID,
        CUSTOMER_ID,
        ORDER_DATE,
        STATUS,
        TOTAL
      ) VALUES (
        l_rows(i).ORDER_ID,
        l_rows(i).CUSTOMER_ID,
        l_rows(i).ORDER_DATE,
        l_rows(i).STATUS,
        l_rows(i).TOTAL
      );

    FORALL i IN INDICES OF l_rows
      DELETE FROM HARNESS_APP.ORDERS
       WHERE ORDER_ID = l_rows(i).ORDER_ID;
  END LOOP;

  CLOSE l_cur;
EXCEPTION
  WHEN OTHERS THEN
    IF l_cur%ISOPEN THEN
      CLOSE l_cur;
    END IF;
    RAISE;
END archive_old_orders;
```

Assumptions:

- “Older than a given date” is implemented as `ORDER_DATE < p_cutoff_date`. If you want the cutoff date to be inclusive, change that predicate to `ORDER_DATE <= p_cutoff_date`.
- The procedure does not commit or rollback; the caller controls transaction completion.
- `ORDERS_ARCHIVE` has the same columns shown in the context: `ORDER_ID`, `CUSTOMER_ID`, `ORDER_DATE`, `STATUS`, and `TOTAL`.
- Batch size is fixed at 10,000 as requested.
- Rows are ordered by `ORDER_ID` so batch boundaries are deterministic. Because `ORDER_ID` is the primary key, there are no ties on the ordering key.
- The procedure has not been compiled or run in this environment.

