DECLARE
  l_failure_count        NUMBER := 0;
  l_min_dept             NUMBER;
  l_no_match_dept        NUMBER;
  l_actual_no_match      NUMBER;
  l_expected_no_match    NUMBER;

  l_match_dept           NUMBER;
  l_actual_match         NUMBER;
  l_expected_match       NUMBER;

  l_actual_null          NUMBER;
  l_expected_null        NUMBER := 0;

  PROCEDURE check_number(
    p_check_name IN VARCHAR2,
    p_expected   IN NUMBER,
    p_actual     IN NUMBER
  ) IS
  BEGIN
    IF p_expected = p_actual THEN
      DBMS_OUTPUT.PUT_LINE(
        'PASS: ' || p_check_name ||
        ' expected=' || NVL(TO_CHAR(p_expected), '<NULL>') ||
        ' actual=' || NVL(TO_CHAR(p_actual), '<NULL>')
      );
    ELSE
      DBMS_OUTPUT.PUT_LINE(
        'FAIL: ' || p_check_name ||
        ' expected=' || NVL(TO_CHAR(p_expected), '<NULL>') ||
        ' actual=' || NVL(TO_CHAR(p_actual), '<NULL>')
      );
      l_failure_count := l_failure_count + 1;
    END IF;
  END check_number;
BEGIN
  SAVEPOINT test_savepoint;

  -- Check 1: a department_id that matches no row.
  BEGIN
    SELECT MIN(department_id) - 1
      INTO l_no_match_dept
      FROM employees;

    SELECT COUNT(*)
      INTO l_expected_no_match
      FROM employees
     WHERE department_id = l_no_match_dept;

    IF l_expected_no_match = 0 THEN
      l_actual_no_match := HARNESS_APP.headcount(l_no_match_dept);
      check_number(
        'headcount for non-matching department_id',
        l_expected_no_match,
        l_actual_no_match
      );
    ELSE
      DBMS_OUTPUT.PUT_LINE(
        'FAIL: setup for non-matching department_id found matching rows for candidate value=' ||
        NVL(TO_CHAR(l_no_match_dept), '<NULL>')
      );
      l_failure_count := l_failure_count + 1;
    END IF;
  EXCEPTION
    WHEN NO_DATA_FOUND THEN
      DBMS_OUTPUT.PUT_LINE(
        'FAIL: setup for non-matching department_id found no MIN(department_id) to derive a candidate value'
      );
      l_failure_count := l_failure_count + 1;
  END;

  -- Check 2: a department_id that matches at least one row.
  BEGIN
    SELECT department_id, cnt
      INTO l_match_dept, l_expected_match
      FROM (
        SELECT department_id, COUNT(*) AS cnt
          FROM employees
         WHERE department_id IS NOT NULL
         GROUP BY department_id
         ORDER BY department_id
      )
     WHERE ROWNUM = 1;

    l_actual_match := HARNESS_APP.headcount(l_match_dept);
    check_number(
      'headcount for matching department_id',
      l_expected_match,
      l_actual_match
    );
  EXCEPTION
    WHEN NO_DATA_FOUND THEN
      DBMS_OUTPUT.PUT_LINE(
        'FAIL: setup for matching department_id found no non-NULL department_id in employees'
      );
      l_failure_count := l_failure_count + 1;
  END;

  -- Check 3: NULL argument. The function uses department_id = p_department_id,
  -- which matches no rows when p_department_id is NULL.
  l_actual_null := HARNESS_APP.headcount(NULL);
  check_number(
    'headcount for NULL department_id',
    l_expected_null,
    l_actual_null
  );

  IF l_failure_count = 0 THEN
    DBMS_OUTPUT.PUT_LINE('SUMMARY: all checks passed');
  ELSE
    DBMS_OUTPUT.PUT_LINE(
      'SUMMARY: ' || l_failure_count || ' check(s) failed'
    );
    ROLLBACK TO test_savepoint;
    RAISE_APPLICATION_ERROR(
      -20999,
      'headcount test block failed: ' || l_failure_count || ' check(s) failed'
    );
  END IF;

  ROLLBACK TO test_savepoint;

EXCEPTION
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('ERROR in headcount test block: ' || SQLERRM);
    ROLLBACK TO test_savepoint;
    RAISE;
END;
```

The block checks three cases. First, it derives a `department_id` value that cannot match any row by taking `MIN(department_id) - 1`; if the table is empty, `MIN(department_id)` is `NULL`, so this setup path raises `NO_DATA_FOUND` and the check prints `FAIL` with its reason. Second, it selects one non-`NULL` `department_id` that has rows and independently computes its expected count; if no such row exists, the setup failure also prints `FAIL`. Third, it calls the function with `NULL`; because the selected function compares with `department_id = p_department_id`, the expected result is `0`, not a count of rows where `department_id IS NULL`.

Each comparison prints `PASS` or `FAIL` with expected and actual values and increments a failure counter. The block uses a savepoint, rolls back to it at the end, and on unexpected exceptions rolls back to it and re-raises. I have not run this block.

